function _login(info) {
  let oriId = String(source.get('aid') || source.get('account_id') || '0')
  if (oriId !== '' && oriId !== '0') {
    return java.longToast('\n❌登录失败，当前已登录，请先退出登录')
  }
  info = info || result
  java.log(JSON.stringify(info))
  let username = info['账号']
  let password = info['密码']
  if (username == '' || password == '') {
    return java.longToast('\n❌登录失败，用户名或密码不能为空')
  }
  let data = requestApiUrl('/console/login', { username: username, password: password }, this)
  // 服务端登录返回的账号字段名两版不一样(v20260907 是 id,v20260930 是 aid),三个名字都认
  let _acc = String((data && (data.aid || data.id || data.account_id)) || '')
  if (!data || !_acc) {
    return java.longToast('\n❌登录失败：服务端没返回账号 id\n接口原始返回：' + JSON.stringify(data) + '\n多半是 token/账号问题,先重新获取 token 再试')
  }
  // 两个变量都写,换版本时不会把已登录状态弄丢
  source.put('aid', _acc)
  source.put('account_id', _acc)
  source.putLoginInfo(JSON.stringify(info))
  java.longToast(`\n✅登录成功\n账号：${_acc}`)
}
