}

result = type == 'video' ? { menus: [] } : requestApiUrl(`/${type}/catalog`, { novelId: novelId }, this)
let menus = Array.from((result && result.menus) || [])
if (!menus.length) {
  // 之前直接吞成空目录 → "目录没了但一声不吭"。失败必须说人话
  try {
    java.longToast('\n❌目录加载失败(0 章)\n接口没返回章节:token 无效/过期,或共享服务器挂了\n👉 先去登录界面重新「获取token」并保存,再重试')
  } catch (_) {}
}

let cache = type == 'video' ? [] : requestApiUrl(`/${type}/cache`, { novelId: novelId }, this) || []
cache = cache.reduce((acc, d) => {
  acc[d.chapId] = d
  return acc
}, {})

let _dtf = null
function formatTime(time) {
  // 每章都 new 一个 Intl 格式化器极慢(实测 2000 章 227ms,手机更慢),整个目录共用一个就够
  if (_dtf === null) {
    try {
      _dtf = new Intl.DateTimeFormat('zh-CN', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      })
    } catch (e) {
      _dtf = false
    }
  }
  let _d = new Date(time)
  if (isNaN(_d.getTime())) return ''
  if (_dtf) return _dtf.format(_d)
  return _d.toLocaleString('zh-CN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit'
  })
}

function toB64(s) {
  // btoa 是纯 JS,省掉每章一次 JS→原生桥调用;不支持时退回 java.base64Encode
  try {
    if (typeof btoa === 'function') return btoa(String(s))
    return java.base64Encode(String(s))
  } catch (e) {
    try { return java.base64Encode(String(s)) } catch (_) { return '' }
  }
}

function formatMenus(menus) {
  menus.forEach(c => {
    let cacheChap = cache[c.id]
    let isShare = !!cacheChap
    let tag = isShare ? '🥑' : ''
    let info = ''
    let onlineTime = (cacheChap && cacheChap.onlineTime) ? cacheChap.onlineTime : formatTime(c.onlineTime)
    if (type == 'novel') {
      info = `${onlineTime} ┃ 字数：${c.volumeNum || 0}`
    } else if (type == 'comic') {
      info = `${onlineTime}${cacheChap ? ` ┃ 图片数：${cacheChap.imageCount || 0}` : ''}`
    } else {
      if (cacheChap) {
        info = `${onlineTime}${cacheChap.duration ? ` ┃ 时长：${cacheChap.durationFormat}` : ''}`
      } else {
        info = onlineTime
      }
    }
    let isVip = c.limit != '游客' && c.limit != '注册会员'
    chaps.push({
      title: isVip ? tag + c.title : c.title,
      info: info + tag,
      isVip: !isShare && isVip,
      // url: getApiUrl(`/${type}/chap`, { novelId: novelId, chapId: c.id })
      url: `data:;base64,${toB64(c.id)},{"type":"${type}","novelId":"${novelId}"}`
    })
  })
}

let chaps = []
if (type == 'novel') {
  book.type = 8
  menus.forEach(v => {
    chaps.push({
      title: v.title,
      voltype: true
    })
    formatMenus(v.children)
  })
} else if (type == 'comic') {
  book.type = 64
  formatMenus(menus)
} else if (type == 'audio') {
  book.type = 32
  formatMenus(menus)
} else if (type == 'video') {
  chaps = [{
    title: '全一集',
    info: '🥑',
    url: `data:;base64,${toB64(novelId)},{"type":"${type}","novelId":"${novelId}"}`
  }]
}

